// ListDeleted returns retired rows still inside the restore window.
func (r *notificationRecipientRepo) ListDeleted(ctx context.Context, f model.NotificationRecipientFilter, page model.NotificationRecipientPage, opts ...readopt.Option) ([]*model.NotificationRecipient, int64, error) {
	ctx, span := r.db.tracer.Start(ctx, "repository.NotificationRecipient.ListDeleted")
	defer span.End()

	// The lifecycle option is forced and the caller's are kept: which rows the
	// trash holds is not up for discussion, and how wide a view of it the caller
	// gets still is.
	return r.list(ctx, f, page, append([]readopt.Option{readopt.WithOnlyDeleted()}, opts...))
}
